<h1>درخواست‌های پشتیبانی</h1><p class="muted">گزارش مشکل، پیشنهاد و پیگیری پاسخ‌ها در همین بخش نگهداری می‌شود.</p><?php if(!$admin): ?><section class="card"><?= $this->start('/support/create') ?><?= $this->field('title','عنوان درخواست') ?><label>نوع<select name="kind"><option value="support">پشتیبانی</option><option value="complaint">شکایت مرتبط با جلسه</option></select></label><?= $this->field('booking_id','شناسه رزرو مرتبط (برای شکایت الزامی)','text','',false) ?><label for="ticket-body">شرح درخواست</label><textarea id="ticket-body" name="body" rows="6" required><?= $this->val('body') ?></textarea><button>ثبت پرونده</button></form></section><?php endif; ?>
<?php foreach($rows as $t): ?><article class="card section"><h2><?= $this->h($t['title']) ?></h2><?php if($admin): ?><p class="support-sender"><span>فرستنده: <?= $this->h($t['sender_name']) ?></span><time data-timestamp="<?= (int)$t['updated_at'] ?>"><?= $this->h(gmdate('Y-m-d H:i',(int)$t['updated_at'])) ?></time></p><?php endif; ?><p><?= $this->status($t['kind']) ?> · <?= $this->status($t['state']) ?></p><a href="<?= $this->h($this->url('/ticket?id='.$t['id'])) ?>">مشاهده پرونده و پاسخ‌ها</a></article><?php endforeach;if(!$rows): ?><p class="card section">پرونده‌ای ثبت نشده است.</p><?php endif; ?>
